+function Get-Factorial {
+    [CmdletBinding()]
+    param(
+        [Parameter(Mandatory)]
+        [ValidateScript({
+            $parsed = 0
+            [int]::TryParse([string]$_, [ref]$parsed) -and $parsed -ge 0
